#!/usr/bin/env python3
"""College Football frontend. Run from repo root. Needs public/data/cfb/*.json. Backs up to *.cfb.bak."""
import base64, os, shutil
FILES = {
  'lib/cfbShared.ts': '',
  'lib/cfb.ts': '',
  'app/teams/cfb/CfbGamesTable.tsx': '',
  'app/teams/cfb/CfbGames.tsx': '',
  'app/teams/cfb/CfbAllTimeTable.tsx': '',
  'app/teams/cfb/page.tsx': '',
  'app/teams/cfb/[slug]/page.tsx': '',
}
OBSOLETE = ["app/teams/cfb/gameRow.tsx", "app/teams/cfb/CfbDecadeGames.tsx"]

def main():
    if not os.path.isdir("app/teams"): print("ABORTED: run from repo root."); raise SystemExit(1)
    for rel in OBSOLETE:
        p = os.path.join(*rel.split("/"))
        if os.path.isfile(p): shutil.move(p, p + ".cfb.bak"); print("  removed " + p)
    for rel, b64 in FILES.items():
        path = os.path.join(*rel.split("/"))
        os.makedirs(os.path.dirname(path), exist_ok=True)
        if os.path.isfile(path): shutil.copyfile(path, path + ".cfb.bak")
        open(path, "wb").write(base64.b64decode(b64)); print("  wrote   " + path)
    print(); print("Done. rm -rf .next, restart npm run dev.")

if __name__ == "__main__": main()
